<?php
namespace App\Console\Commands;
use App\Models\{AssetBalance,Trade,User,WalletTransaction};use Illuminate\Console\Command;use Illuminate\Support\Facades\DB;
class ExpireTrades extends Command {protected $signature='trading:expire-orders';protected $description='Cancel expired unaccepted orders and return reserved assets or money';public function handle():int {Trade::where('status','submitted')->where('expires_at','<=',now())->cursor()->each(function($trade){DB::transaction(function()use($trade){$trade->refresh();if($trade->status!=='submitted')return;$user=User::lockForUpdate()->find($trade->user_id);if($trade->side==='sell'){$user->increment('wallet_balance',$trade->total_price);WalletTransaction::create(['user_id'=>$user->id,'amount'=>$trade->total_price,'type'=>'trade_expiry_refund','reference_type'=>Trade::class,'reference_id'=>$trade->id,'description'=>'بازگشت وجه سفارش منقضی']);}else{AssetBalance::firstOrCreate(['user_id'=>$user->id,'asset'=>$trade->unit==='gram'?'gold_9999':'gold_995'])->increment('quantity',$trade->quantity);}$trade->update(['status'=>'rejected']);});});return self::SUCCESS;}}
